// the shader clock the GPU actually runs at under load: clock64() (shader cycles) against wall_clock64() (100 MHz)
#include <hip/hip_runtime.h>
#include <cstdio>
#include <cstdlib>
__global__ void spin(long long* out, long long ticks) {
    const long long w0 = wall_clock64(), c0 = clock64();
    float x = threadIdx.x * 1.0001f;
    while (wall_clock64() - w0 < ticks) {
        #pragma unroll
        for (int i = 0; i < 64; ++i) x = x * 1.000001f + 0.5f;
    }
    if (threadIdx.x == 0 && blockIdx.x == 0) { out[0] = wall_clock64() - w0; out[1] = clock64() - c0; }
    if (x == 12345.f) out[2] = 1;
}
int main(int argc, char** argv) {
    const int reps = argc > 1 ? std::atoi(argv[1]) : 5;
    const int blocks = argc > 2 ? std::atoi(argv[2]) : 40;
    long long* d; hipMallocManaged(&d, 32);
    for (int r = 0; r < reps; ++r) {
        spin<<<blocks, 256>>>(d, 50000000);   // 0.5 s at 100 MHz
        hipDeviceSynchronize();
        std::printf("sample %d: wall %.3f s, shader clock %.0f MHz\n", r, d[0] / 1e8, d[1] / (d[0] / 1e8) / 1e6);
    }
    return 0;
}

