import pathlib, sys
p = pathlib.Path("src/kernels/qsa_prompt_attn_parity.cpp"); s = p.read_text(encoding="utf-8")
old = '''        if (std::strncmp(prop.gcnArchName, "gfx12", 5) != 0) {
